#!/usr/bin/env python3
"""hooks/worktree-guard.py — enforce canonical worktree placement.

Implements ~/.ai/Common.md §U17 (Worktree placement). Two canonical
locations only:

  <repo>/.worktrees/<name>/   (single-repo, dies with the repo)
  ~/.ai/worktrees/<name>/     (cross-repo, persistent)

Ad-hoc placement (`../<branch>/`, `/tmp/worktree-X/`, sibling
directories of the repo, etc.) is forbidden.

Triggers on `git worktree add <path> ...`. Other `git worktree`
subcommands (list, remove, prune) are passed through.

Two invocation modes:
  PreToolUse  — reads a JSON event from stdin; on violation emits a
                JSON permissionDecision deny on stdout and exits 0.
                (Claude Code path via hooks.PreToolUse in settings.json)
  wrapper     — invoked as `python <hook> --mode=wrapper` by `ai wrap git`;
                reads git argv from $WRAPPED_ARGV; on violation writes to
                stderr and exits non-zero to block the real git binary.

Self-check:
  --self-check
"""
from __future__ import annotations

import json
import os
import shlex
import subprocess
import sys
from pathlib import Path
from typing import List, Optional

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _lib  # noqa: E402

# Flags on `git worktree add` that consume the next token as a value.
# Anything else starting with `-` is treated as value-less.
VALUE_FLAGS = {"-b", "-B", "--reason"}

# Shell operators that separate one command from the next. shlex.split
# (posix) emits these as standalone tokens, so we segment on them.
SHELL_SEPARATORS = {";", "&&", "||", "|", "&"}

# `git` global options (before the subcommand) that consume the next
# token as their value, e.g. `git -C <dir> worktree add`.
GIT_GLOBAL_VALUE_OPTS = {
    "-C", "-c", "--git-dir", "--work-tree",
    "--namespace", "--exec-path", "--super-prefix",
}


def deny_pretooluse(reason: str) -> None:
    """Emit a PreToolUse permission-deny decision (stdout) and exit 0."""
    print(json.dumps({
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "deny",
            "permissionDecisionReason": reason,
        }
    }))
    sys.exit(0)


def violation_message(raw_path: str, cwd: str) -> str:
    """Build the human-readable §U17 violation message for raw_path."""
    p = Path(raw_path)
    if not p.is_absolute():
        p = Path(cwd) / p
    try:
        shown = p.resolve()
    except Exception:
        shown = p

    repo_root = resolve_repo_root(cwd)
    ai_root = ai_worktrees_root()
    hints = []
    if repo_root:
        hints.append(f"  {repo_root}/.worktrees/<name>/  — single-repo")
    hints.append(f"  {ai_root}/<name>/  — cross-repo or persistent")
    hints_block = "\n".join(hints)
    return (
        "Worktree placement violates Common.md §U17.\n"
        f"  Target: {shown}\n"
        "Canonical roots:\n"
        f"{hints_block}\n"
        "Choose by lifecycle (§U17.1) and re-run.\n"
        "Preferred surface: `ai worktree add <name>` "
        "(with `--global` for cross-repo)."
    )


def ai_worktrees_root() -> Path:
    """Return the cross-repo canonical worktree root."""
    ai_root = os.environ.get("AI_ROOT", str(Path.home() / ".ai"))
    return Path(ai_root) / "worktrees"


def _clean_path_env() -> dict:
    """Return os.environ with the AI shim bin dirs stripped from PATH.

    resolve_repo_root must reach the real git, not the ~/.ai/bin/git
    governance shim. Routing this hook's own internal git through the
    shim re-enters the `ai wrap` pipeline; in wrapper mode the shimmed
    `git rev-parse` does not return within the timeout, so the repo root
    resolves empty and a canonical <repo>/.worktrees/ target is wrongly
    rejected (observed: the call hit its ~5s timeout). Strip both
    $AI_ROOT/bin and the canonical ~/.ai/bin.
    """
    # Collect all AI bin dirs to strip: the canonical one and any override.
    canonical_ai_bin = Path.home() / ".ai" / "bin"
    env_ai_root = os.environ.get("AI_ROOT", "")
    override_ai_bin = Path(env_ai_root) / "bin" if env_ai_root else None

    strip = {str(canonical_ai_bin.resolve())}
    if override_ai_bin is not None:
        try:
            strip.add(str(override_ai_bin.resolve()))
        except Exception:
            strip.add(str(override_ai_bin))

    raw_path = os.environ.get("PATH", "")
    cleaned_parts = []
    for p in raw_path.split(os.pathsep):
        if not p:
            continue
        try:
            resolved = str(Path(p).resolve())
        except Exception:
            resolved = p
        if resolved not in strip and p not in strip:
            cleaned_parts.append(p)
    env = dict(os.environ)
    env["PATH"] = os.pathsep.join(cleaned_parts)
    return env


def resolve_repo_root(cwd: str) -> Optional[Path]:
    """Return the repo root for the given working directory, or None."""
    try:
        out = subprocess.run(
            ["git", "-C", cwd, "rev-parse", "--show-toplevel"],
            capture_output=True, text=True, timeout=5,
            env=_clean_path_env(),
        )
        if out.returncode == 0 and out.stdout.strip():
            return Path(out.stdout.strip()).resolve()
    except Exception:
        pass
    return None


def _normalize_tokens(tokens: List[str]) -> List[str]:
    """Expand tokens that have trailing shell operators glued on.

    shlex.split(posix=True) merges a quoted token with an adjacent
    semicolon (e.g. `"===";` becomes `===;`). Strip any trailing
    semicolons and re-insert them as separate tokens so the segmenter
    can treat them uniformly.
    """
    result: List[str] = []
    for tok in tokens:
        # Only strip trailing semicolons; other operators are always
        # standalone tokens from shlex.split.
        if tok.endswith(";") and tok != ";":
            result.append(tok[:-1])
            result.append(";")
        else:
            result.append(tok)
    return result


def _split_segments(tokens: List[str]) -> List[List[str]]:
    """Split a flat token list into command segments on shell operators."""
    segments: List[List[str]] = []
    current: List[str] = []
    for tok in _normalize_tokens(tokens):
        if tok in SHELL_SEPARATORS:
            if current:
                segments.append(current)
                current = []
        else:
            current.append(tok)
    if current:
        segments.append(current)
    return segments


def _is_env_assignment(tok: str) -> bool:
    """True for a leading `VAR=value` shell environment assignment."""
    if tok.startswith("-") or "=" not in tok:
        return False
    return tok.split("=", 1)[0].isidentifier()


def _path_after_add(seg: List[str], i: int) -> Optional[str]:
    """Return the positional path argument following `worktree add`."""
    n = len(seg)
    while i < n:
        tok = seg[i]
        if tok == "--":
            i += 1
            break
        if not tok.startswith("-"):
            return tok
        if tok in VALUE_FLAGS and i + 1 < n:
            i += 2
            continue
        i += 1  # value-less flag (e.g. --detach, --lock, --quiet)
    if i < n:
        return seg[i]
    return None


def _worktree_add_path_in_segment(seg: List[str]) -> Optional[str]:
    """Return the target path if this segment is a `git worktree add`."""
    i, n = 0, len(seg)
    while i < n and _is_env_assignment(seg[i]):
        i += 1
    if i >= n or seg[i] != "git":
        return None
    i += 1
    # Skip git global options (`-C <dir>`, `-c k=v`, `--no-pager`, ...).
    while i < n and seg[i].startswith("-"):
        opt = seg[i]
        if "=" in opt:
            i += 1
        elif opt in GIT_GLOBAL_VALUE_OPTS and i + 1 < n:
            i += 2
        else:
            i += 1
    if i + 1 >= n or seg[i] != "worktree" or seg[i + 1] != "add":
        return None
    return _path_after_add(seg, i + 2)


def find_worktree_add_path(tokens: List[str]) -> Optional[str]:
    """Return the target path for a `git worktree add` anywhere in tokens.

    Scans every shell segment, so compound commands
    (`cd x && git worktree add <path>`) and git global options
    (`git -C dir worktree add <path>`) are all detected. Returns None
    if no `git worktree add` invocation is present.
    """
    for seg in _split_segments(tokens):
        path = _worktree_add_path_in_segment(seg)
        if path is not None:
            return path
    return None


def is_canonical(raw_path: str, cwd: str) -> bool:
    """Return True if raw_path resolves to a canonical worktree location."""
    target = Path(raw_path)
    if not target.is_absolute():
        target = Path(cwd) / target
    try:
        resolved = target.resolve()
    except Exception:
        resolved = Path(os.path.normpath(str(target)))

    # Check: ~/.ai/worktrees/<name>/ (or $AI_ROOT/worktrees/)
    ai_root = ai_worktrees_root()
    try:
        resolved.relative_to(ai_root.resolve())
        return True
    except (ValueError, FileNotFoundError):
        pass

    # Check: <repo>/.worktrees/<name>/
    repo_root = resolve_repo_root(cwd)
    if repo_root is not None:
        try:
            resolved.relative_to(repo_root / ".worktrees")
            return True
        except ValueError:
            pass

    return False


def run_pretooluse_mode() -> int:
    """Claude Code PreToolUse path: parse a JSON event from stdin."""
    raw = sys.stdin.read()
    if not raw.strip():
        return 0
    try:
        event = json.loads(raw)
    except json.JSONDecodeError:
        return 0
    hook_event = event.get("hookEventName") or event.get("hook_event_name") or ""
    if hook_event != "PreToolUse":
        return 0
    tool_name = event.get("tool_name") or event.get("toolName") or ""
    if tool_name not in ("Bash", "shell", "execute"):
        return 0
    tool_input = event.get("tool_input") or event.get("toolInput") or {}
    if not isinstance(tool_input, dict):
        return 0
    command = tool_input.get("command") or ""
    if not isinstance(command, str) or "worktree" not in command:
        return 0
    cwd = event.get("cwd") or os.getcwd()
    try:
        tokens = shlex.split(command, comments=False, posix=True)
    except ValueError:
        return 0
    target = find_worktree_add_path(tokens)
    if target is None:
        return 0
    if not is_canonical(target, cwd):
        deny_pretooluse(violation_message(target, cwd))
    return 0


def run_wrapper_mode() -> int:
    """Client-agnostic `ai wrap git` path: git argv arrives in $WRAPPED_ARGV.

    Returns non-zero to block the real git binary on a §U17 violation.
    """
    argv_json = os.environ.get("WRAPPED_ARGV", "")
    if not argv_json:
        return 0
    try:
        argv = json.loads(argv_json)
    except json.JSONDecodeError:
        return 0
    if not isinstance(argv, list):
        return 0
    # $WRAPPED_ARGV holds the args *after* `git`; prepend it so the
    # shared segment parser sees a normal `git ... worktree add` shape.
    tokens = ["git"] + [str(a) for a in argv]
    if "worktree" not in tokens:
        return 0
    target = find_worktree_add_path(tokens)
    if target is None:
        return 0
    cwd = os.getcwd()
    if is_canonical(target, cwd):
        return 0
    sys.stderr.write(violation_message(target, cwd) + "\n")
    return 1


def main() -> int:
    if "--self-check" in sys.argv:
        return _lib.self_check_ok()
    if "--mode=wrapper" in sys.argv or os.environ.get("WRAPPED_CMD"):
        return run_wrapper_mode()
    return run_pretooluse_mode()


if __name__ == "__main__":
    sys.exit(main())
